import React, { useState } from "react";

function FormHandeling() {
  const [formvalue, setFormhandel] = useState({
    id: "",
    name: "",
    email: "",
    password: "",
  });

  const [data, setData] = useState([]);
  const [editId, setEditId] = useState(null); 


  const changeHandel = (e) => {
    setFormhandel({
      ...formvalue,
      [e.target.name]: e.target.value,
    });
  };


  const submitHandel = (e) => {
    e.preventDefault();

    if (editId) {
      const updatedData = data.map((item) =>
        item.id === editId ? { ...formvalue, id: editId } : item
      );
      setData(updatedData);
      setEditId(null);
    } else {
      const newData = {
        ...formvalue,
        id: new Date().getTime().toString(),
      };
      setData([...data, newData]);
    }

    setFormhandel({ id: "", name: "", email: "", password: "" });
  };

  const deleteHandel = (id) => {
    const filterdata = data.filter((value) => value.id !== id);
    setData(filterdata);
  };

  const editHandel = (item) => {
    setFormhandel(item);
    setEditId(item.id);
  };

  return (
    <div className="bg-light min-vh-100 py-5">
      <div className="container">

        <div className="card shadow mb-4">
          <div className="card-header bg-primary text-white text-center">
            <h4>{editId ? "Update User" : "User Register"}</h4>
          </div>

          <div className="card-body">
            <form onSubmit={submitHandel}>
              <div className="row">
                <div className="col-md-4 mb-3">
                    <label>Name:</label>
<input type="text" name="name" value={formvalue.name} onChange={changeHandel}
className="form-control" placeholder="Enter Name" required />
</div><br/>

                <div className="col-md-4 mb-3">
                  <input
                    type="email"
                    name="email"
                    value={formvalue.email}
                    onChange={changeHandel}
                    className="form-control"
                    placeholder="Enter Email"
                    required
                  />
                </div>

                <div className="col-md-4 mb-3">
                  <input
                    type="password"
                    name="password"
                    value={formvalue.password}
                    onChange={changeHandel}
                    className="form-control"
                    placeholder="Enter Password"
                    required
                  />
                </div>
              </div>

              <button className="btn btn-success w-100">
                {editId ? "Update " : "Submit "}
              </button>
            </form>
          </div>
        </div>

        <div className="card shadow">
          <div className="card-header bg-dark text-white text-center">
            <h4>User Manage</h4>
          </div>

          <div className="card-body">
            <table className="table table-bordered table-hover text-center">
              <thead className="table-dark">
                <tr>
                  <th>ID</th>
                  <th>Name</th>
                  <th>Email</th>
                  <th>Password</th>
                  <th>Action</th>
                </tr>
              </thead>

              <tbody>
                {data.length > 0 ? (
                  data.map((value) => (
                    <tr key={value.id}>
                      <td>{value.id}</td>
                      <td>{value.name}</td>
                      <td>{value.email}</td>
                      <td>{value.password}</td>
                      <td>
                        <button
                          onClick={() => editHandel(value)}
                          className="btn btn-warning btn-sm me-2"
                        >
                          Edit 
                        </button>

                        <button
                          onClick={() => deleteHandel(value.id)}
                          className="btn btn-danger btn-sm"
                        >
                          Delete 
                        </button>
                      </td>
                    </tr>
                  ))
                ) : (
                  <tr>
                    <td colSpan="5">No Data Found</td>
                  </tr>
                )}
              </tbody>
            </table>
          </div>
        </div>

      </div>
    </div>
  );
}

export default FormHandeling;
